import { useEffect, useRef, useState } from "react";
import ReactMarkdown from "react-markdown";
import remarkGfm from "remark-gfm";
import recap from "virtual:spec-recap";
import config from "virtual:spec-config";
import { Modal, ModalClose } from "./Modal";
import { cn } from "./lib/utils";
import { PROSE } from "./prose";

/**
 * The Summary modal: `<specsDir>/RECAP.md` rendered, with the raw markdown one click
 * away.
 *
 * The recap is generated by `/spec-recap` and is plain markdown, not a ticket, so the
 * board renders it and never parses it into fields. The one thing it does read out is
 * the `updated:` stamp, because a recap whose age you cannot see is worse than no recap.
 */

/**
 * Pull the `updated:` stamp out of the head of the file.
 *
 * Lenient on purpose. `/spec-recap` writes `updated:` and `window:` as the first two
 * lines, but the file is hand-editable and a missing stamp is not an error: the modal
 * then shows the recap with no date rather than refusing to render it. Only the head is
 * searched, so an `updated:` inside a bullet further down cannot masquerade as one.
 */
export function updatedStamp(raw: string): string | null {
  for (const line of raw.split("\n").slice(0, 6)) {
    const m = /^\s*updated:\s*(\S.*?)\s*$/i.exec(line);
    if (m) return m[1];
  }
  return null;
}

/**
 * Copy text to the clipboard, with the pre-async-API fallback.
 *
 * `navigator.clipboard` needs a secure context. `http://localhost` counts, so the
 * normal path works, but a board opened over the LAN (`vite --host`) does not, and
 * there the async API is simply absent. The textarea + `execCommand` route is
 * deprecated and still the only thing that works in that case.
 */
async function copyText(text: string): Promise<boolean> {
  try {
    await navigator.clipboard.writeText(text);
    return true;
  } catch {
    try {
      const ta = document.createElement("textarea");
      ta.value = text;
      ta.setAttribute("readonly", "");
      // Off-screen but focusable: `display: none` cannot be selected.
      ta.style.position = "fixed";
      ta.style.top = "-1000px";
      ta.style.opacity = "0";
      document.body.appendChild(ta);
      ta.select();
      const ok = document.execCommand("copy");
      document.body.removeChild(ta);
      return ok;
    } catch {
      return false;
    }
  }
}

function CopyButton({ text }: { text: string }) {
  const [state, setState] = useState<"idle" | "copied" | "failed">("idle");
  const timer = useRef<ReturnType<typeof setTimeout> | null>(null);

  // The label reverts on a timer, so an unmount mid-flight must not fire setState.
  useEffect(() => () => {
    if (timer.current !== null) clearTimeout(timer.current);
  }, []);

  return (
    <button
      type="button"
      onClick={async () => {
        const ok = await copyText(text);
        setState(ok ? "copied" : "failed");
        if (timer.current !== null) clearTimeout(timer.current);
        timer.current = setTimeout(() => setState("idle"), 1500);
      }}
      title="Copy the raw markdown"
      className={cn(
        "rounded-lg border px-2.5 py-1 text-[12px] font-medium transition-colors",
        state === "copied"
          ? "border-primary bg-primary text-primary-foreground"
          : "border-border bg-card text-muted-foreground hover:border-ring hover:text-foreground",
      )}
    >
      {state === "copied" ? "Copied" : state === "failed" ? "Copy failed" : "Copy"}
    </button>
  );
}

export function RecapModal({ onClose }: { onClose: () => void }) {
  const stamp = recap.exists ? updatedStamp(recap.raw) : null;

  return (
    <Modal onClose={onClose} labelledBy="recap-title">
      <div className="flex items-start justify-between gap-3 border-b border-border px-6 py-4">
        <div className="min-w-0">
          <h2 id="recap-title" className="text-lg font-bold leading-tight text-foreground">
            Summary
          </h2>
          {stamp && (
            <div className="mt-0.5 text-[11px] text-muted-foreground">updated {stamp}</div>
          )}
        </div>
        <div className="flex shrink-0 items-center gap-2">
          {recap.exists && <CopyButton text={recap.raw} />}
          <ModalClose onClose={onClose} />
        </div>
      </div>

      <div className="px-6 py-5">
        {recap.exists ? (
          <article className={PROSE}>
            <ReactMarkdown remarkPlugins={[remarkGfm]}>{recap.raw}</ReactMarkdown>
          </article>
        ) : (
          <p className="text-[13px] text-muted-foreground">
            No recap yet. Run <code className="font-mono">/spec-recap</code> to generate{" "}
            <span className="font-mono">{config.specsDir}/RECAP.md</span>.
          </p>
        )}
      </div>
    </Modal>
  );
}
